/**
 * Driver art generator (2026-05-23).
 *
 * Generates two assets per driver from data/art/drivers.json:
 *   apps/web/public/images/drivers/numbers/<racingNumber>.svg
 *     a clean racing-number plate in the driver's primary team colour
 *     for the driver's most recent season
 *   apps/web/public/images/drivers/avatars/<slug>.svg
 *     a minimalist circular avatar with the driver code letters,
 *     coloured by team (used as the fallback when no photo is available)
 *
 * Driver portraits (raster) are NOT generated by this script. They are
 * downloaded manually from formula1.com/en/drivers per attribution and
 * dropped into apps/web/public/images/drivers/<slug>.webp. The portrait
 * field in drivers.json points at that target path; consumers fall back
 * to the SVG avatar when the .webp is missing.
 *
 * Flags:
 *   --force      regenerate even when files already exist
 *   --slug=...   only process the matching driver slug
 */

import { mkdir, readFile, writeFile, access, constants } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");

function parseFlags(argv) {
  const flags = { force: false, slug: null };
  for (const a of argv.slice(2)) {
    if (a === "--force") flags.force = true;
    else if (a.startsWith("--slug=")) flags.slug = a.slice("--slug=".length);
  }
  return flags;
}

async function exists(p) {
  try { await access(p, constants.F_OK); return true; } catch { return false; }
}

function escapeXml(s) {
  return String(s).replace(/[<>&"']/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;", "'": "&apos;" }[c]));
}

function teamColors(teams, slug) {
  const team = teams.find((t) => t.slug === slug);
  return team ? { base: team.baseColor, accent: team.accentColor || "#ffffff" } : { base: "#9ca3af", accent: "#ffffff" };
}

function numberPlateSvg(driver, baseColor, accentColor) {
  const num = String(driver.racingNumber);
  const fontSize = num.length === 1 ? 138 : num.length === 2 ? 110 : 90;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 160" role="img" aria-label="${escapeXml(driver.fullName)} #${num}">
  <defs>
    <linearGradient id="numbg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="${escapeXml(baseColor)}"/>
      <stop offset="100%" stop-color="${escapeXml(accentColor)}" stop-opacity="0.78"/>
    </linearGradient>
  </defs>
  <rect x="6" y="6" width="208" height="148" rx="20" fill="url(#numbg)"/>
  <rect x="6" y="6" width="208" height="148" rx="20" fill="none" stroke="rgba(255,255,255,0.55)" stroke-width="3"/>
  <text x="110" y="100" text-anchor="middle" dominant-baseline="middle"
        font-family="Aptos, 'Segoe UI', system-ui, sans-serif"
        font-weight="900" font-size="${fontSize}" fill="#ffffff" letter-spacing="-3">${escapeXml(num)}</text>
  <text x="110" y="142" text-anchor="middle" dominant-baseline="middle"
        font-family="'IBM Plex Mono', Consolas, monospace"
        font-weight="700" font-size="14" fill="rgba(255,255,255,0.82)" letter-spacing="3">${escapeXml(driver.code)}</text>
</svg>
`;
}

function avatarSvg(driver, baseColor, accentColor) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96" role="img" aria-label="${escapeXml(driver.fullName)}">
  <defs>
    <radialGradient id="bg" cx="0.3" cy="0.25" r="0.95">
      <stop offset="0%" stop-color="${escapeXml(accentColor)}" stop-opacity="0.4"/>
      <stop offset="100%" stop-color="${escapeXml(baseColor)}"/>
    </radialGradient>
  </defs>
  <circle cx="48" cy="48" r="44" fill="url(#bg)" stroke="rgba(255,255,255,0.55)" stroke-width="2"/>
  <text x="48" y="52" text-anchor="middle" dominant-baseline="middle"
        font-family="Aptos, system-ui, sans-serif"
        font-weight="900" font-size="32" fill="#ffffff" letter-spacing="1">${escapeXml(driver.code)}</text>
  <text x="48" y="74" text-anchor="middle" dominant-baseline="middle"
        font-family="'IBM Plex Mono', Consolas, monospace"
        font-weight="700" font-size="11" fill="rgba(255,255,255,0.78)">#${escapeXml(String(driver.racingNumber))}</text>
</svg>
`;
}

async function processDriver(driver, teams, flags, outputs) {
  // Use the most recent season's team for colour.
  const sortedSeasons = [...driver.seasons].sort((a, b) => b.season - a.season);
  const teamSlug = sortedSeasons[0]?.team;
  const colours = teamColors(teams, teamSlug);

  const numberDir = path.join(root, "apps", "web", "public", "images", "drivers", "numbers");
  await mkdir(numberDir, { recursive: true });
  const avatarDir = path.join(root, "apps", "web", "public", "images", "drivers", "avatars");
  await mkdir(avatarDir, { recursive: true });

  const numberPath = path.join(numberDir, `${driver.racingNumber}.svg`);
  const avatarPath = path.join(avatarDir, `${driver.slug}.svg`);

  if (!flags.force && await exists(numberPath)) {
    outputs.push({ slug: driver.slug, file: `numbers/${driver.racingNumber}.svg`, action: "skip" });
  } else {
    await writeFile(numberPath, numberPlateSvg(driver, colours.base, colours.accent), "utf-8");
    outputs.push({ slug: driver.slug, file: `numbers/${driver.racingNumber}.svg`, action: "wrote" });
  }

  if (!flags.force && await exists(avatarPath)) {
    outputs.push({ slug: driver.slug, file: `avatars/${driver.slug}.svg`, action: "skip" });
  } else {
    await writeFile(avatarPath, avatarSvg(driver, colours.base, colours.accent), "utf-8");
    outputs.push({ slug: driver.slug, file: `avatars/${driver.slug}.svg`, action: "wrote" });
  }
}

async function main() {
  const flags = parseFlags(process.argv);
  const driversPath = path.join(root, "apps", "web", "src", "data", "art", "drivers.json");
  const teamsPath = path.join(root, "apps", "web", "src", "data", "art", "teams.json");
  const driversManifest = JSON.parse(await readFile(driversPath, "utf-8"));
  const teamsManifest = JSON.parse(await readFile(teamsPath, "utf-8"));
  const drivers = flags.slug
    ? driversManifest.drivers.filter((d) => d.slug === flags.slug)
    : driversManifest.drivers;
  if (!drivers.length) {
    process.stderr.write(`No drivers matched slug=${flags.slug}\n`);
    process.exit(1);
  }
  const outputs = [];
  for (const driver of drivers) {
    await processDriver(driver, teamsManifest.teams, flags, outputs);
  }
  const wrote = outputs.filter((o) => o.action === "wrote").length;
  const skip = outputs.filter((o) => o.action === "skip").length;
  process.stdout.write(`Driver art: wrote=${wrote}, skipped=${skip}, force=${flags.force}\n`);
}

main().catch((error) => {
  process.stderr.write(`${error instanceof Error ? error.stack || error.message : error}\n`);
  process.exit(1);
});
